-- 037_crop_types.sql
-- Crop types, their growing targets, and a crop choice per device.
--
-- A user picks the crop a CW-SS soil sensor sits in (device settings). The app
-- then judges that sensor's readings against the crop's targets: below, inside
-- or above the optimal band, or past a stress limit.
--
--   cw_crop_types           one row per crop: stable `code`, English/Japanese
--                           names, category, greenhouse / open field.
--   cw_crop_targets         one row per crop × metric × period of the day:
--                           min_value ≤ optimal_min ≤ optimal_max ≤ max_value
--                           (optimal band inside the stress limits), in a fixed
--                           unit per metric (checked), with notes on the basis
--                           (growth stage, unit conversion) and the source URLs
--                           the values came from.
--   cw_devices.crop_type_id the device's crop; NULL = none chosen. Deleting a
--                           crop type clears it on its devices.
--
-- period: a 'day' row is judged in daylight only, a 'night' row at night only,
-- an 'all' row at any time. Air temperature and humidity have a day and a night
-- row; CO₂, PPFD and VPD are day-only; the soil metrics and DLI are 'all'.
--
-- Metrics and units:
--   soil_temperature °C, soil_water_tension kPa (the texture-independent basis
--   of soil_moisture), soil_moisture % (volumetric water content, loam),
--   soil_ec mS/cm (bulk EC as an in-soil probe reads it), soil_ec_1to5 mS/cm
--   (lab soil test, 1:5 extract), soil_ph pH, air_temperature °C,
--   air_humidity % (RH), co2 ppm, ppfd µmol/m²/s, dli mol/m²/day, vpd kPa.
-- A metric is a row, not a column, so adding one needs no migration.
--
-- The seed holds researched reference values for the main crops, each with
-- sources. The soil moisture bands assume a loam soil: volcanic-ash (黒ボク)
-- soils hold far more water, so soil_water_tension is kept for converting.
--
-- Additive and re-runnable (IF NOT EXISTS / ON CONFLICT). The new tables are
-- service-role only (RLS on, anon/authenticated revoked), like the other
-- API-only tables: the API serves the crop list and the device setting.
-- Run before deploying the API that reads them. Patch database.types.ts (api +
-- CropWatch) after.

BEGIN;

-- Fail fast instead of queueing behind a long read on cw_devices.
SET LOCAL lock_timeout = '5s';

CREATE TABLE IF NOT EXISTS public.cw_crop_types (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code        text NOT NULL UNIQUE
                CONSTRAINT cw_crop_types_code_format CHECK (code ~ '^[a-z][a-z0-9_]*$'),
    name_en     text NOT NULL,
    name_ja     text NOT NULL,
    category    text NOT NULL
                CONSTRAINT cw_crop_types_category CHECK (category IN (
                    'fruiting_vegetable', 'leafy_vegetable', 'root_vegetable', 'allium', 'field_crop',
                    'tree_fruit', 'small_fruit', 'tea', 'herb', 'flower')),
    cultivation text NOT NULL DEFAULT 'both'
                CONSTRAINT cw_crop_types_cultivation CHECK (cultivation IN ('greenhouse', 'open_field', 'both')),
    notes       text,
    sort_order  integer NOT NULL DEFAULT 0,
    is_active   boolean NOT NULL DEFAULT true,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.cw_crop_targets (
    crop_type_id bigint NOT NULL REFERENCES public.cw_crop_types (id) ON DELETE CASCADE,
    metric       text NOT NULL,
    period       text NOT NULL DEFAULT 'all'
                 CONSTRAINT cw_crop_targets_period CHECK (period IN ('all', 'day', 'night')),
    unit         text NOT NULL,
    min_value    numeric,
    optimal_min  numeric,
    optimal_max  numeric,
    max_value    numeric,
    notes        text,
    sources      text[] NOT NULL DEFAULT '{}',
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (crop_type_id, metric, period),
    -- One fixed unit per metric, so readings can be compared without conversion.
    CONSTRAINT cw_crop_targets_metric_unit CHECK ((metric, unit) IN (
        ('soil_temperature', '°C'), ('soil_water_tension', 'kPa'), ('soil_moisture', '%'),
        ('soil_ec', 'mS/cm'), ('soil_ec_1to5', 'mS/cm'), ('soil_ph', 'pH'),
        ('air_temperature', '°C'), ('air_humidity', '%'), ('co2', 'ppm'),
        ('ppfd', 'µmol/m²/s'), ('dli', 'mol/m²/day'), ('vpd', 'kPa'))),
    -- The optimal band sits inside the stress limits (unset bounds are skipped).
    CONSTRAINT cw_crop_targets_band_order CHECK (
        (min_value IS NULL OR optimal_min IS NULL OR min_value <= optimal_min)
        AND (optimal_min IS NULL OR optimal_max IS NULL OR optimal_min <= optimal_max)
        AND (optimal_max IS NULL OR max_value IS NULL OR optimal_max <= max_value)
        AND (min_value IS NULL OR max_value IS NULL OR min_value <= max_value))
);

ALTER TABLE public.cw_crop_types ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.cw_crop_types FROM anon, authenticated;
ALTER TABLE public.cw_crop_targets ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.cw_crop_targets FROM anon, authenticated;

ALTER TABLE public.cw_devices
    ADD COLUMN IF NOT EXISTS crop_type_id bigint REFERENCES public.cw_crop_types (id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS cw_devices_crop_type_id_idx ON public.cw_devices (crop_type_id);

COMMENT ON TABLE public.cw_crop_types IS 'Crops a soil sensor can be set to; see cw_crop_targets.';
COMMENT ON TABLE public.cw_crop_targets IS
    'Growing targets per crop, metric and period: optimal band [optimal_min, optimal_max] inside stress limits [min_value, max_value].';
COMMENT ON COLUMN public.cw_crop_targets.period IS
    'When the row applies: day (daylight only), night (night only) or all (any time).';
COMMENT ON COLUMN public.cw_devices.crop_type_id IS 'Crop the device monitors (soil sensors); NULL = not set.';

-- ---------------------------------------------------------------------------
-- Seed: researched reference values (sources on each row)
-- ---------------------------------------------------------------------------

INSERT INTO public.cw_crop_types (code, name_en, name_ja, category, cultivation, notes, sort_order)
VALUES
    ('tomato', 'Tomato', 'トマト', 'fruiting_vegetable', 'both', 'Established, fruit-producing plants in mineral soil; stage, cultivar and rootstock can change targets. Null means unknown, not zero or safe; EC basis and daylight assumptions must be respected.', 10),
    ('cherry_tomato', 'Cherry tomato', 'ミニトマト', 'fruiting_vegetable', 'both', 'Established fruit-producing plants in mineral soil; Awa cherry-tomato daytime/water guidance and Aichi cherry-specific night adjustment are used. Other targets remain labelled tomato-species proxies; null is unknown, and seasonal daylight and measurement basis must be respected.', 20),
    ('cucumber', 'Cucumber', 'キュウリ', 'fruiting_vegetable', 'both', 'Established, fruit-producing plants in mineral soil; stage, cultivar and rootstock can change targets. Null means unknown, not zero or safe; EC basis and daylight assumptions must be respected.', 30),
    ('sweet_pepper', 'Sweet pepper (paprika / bell pepper)', 'パプリカ・ピーマン', 'fruiting_vegetable', 'both', 'Established, fruit-producing plants in mineral soil; stage, cultivar and rootstock can change targets. Null means unknown, not zero or safe; EC basis and daylight assumptions must be respected. Japanese piman environmental guidance is a proxy for paprika/bell pepper; EC is a device-specific field reference.', 40),
    ('poblano_pepper', 'Poblano pepper', 'ポブラノ', 'fruiting_vegetable', 'both', 'Capsicum annuum poblano (ancho when dried). No poblano-specific research was found, so every target is the bell pepper (sweet_pepper) target from Japanese greenhouse sources, as the grower decided on 2026-11-08. Null means unverified, not safe.', 50),
    ('strawberry', 'Strawberry', 'イチゴ', 'fruiting_vegetable', 'greenhouse', 'Established, fruit-producing plants in mineral soil; stage, cultivar and rootstock can change targets. Null means unknown, not zero or safe; EC basis and daylight assumptions must be respected.', 60),
    ('grape', 'Grape', 'ブドウ', 'tree_fruit', 'both', 'Japanese table-grape reference for active growth, centered on Kyoho and Shine Muscat; exclude winter dormancy. Cultivar, stage and greenhouse overrides are necessary: this schema cannot represent them; wine-grape deficit irrigation is not the table-grape default. Null means unverified, not safe; conditional limits require duration and context.', 70)
ON CONFLICT (code) DO UPDATE SET
    name_en = EXCLUDED.name_en, name_ja = EXCLUDED.name_ja, category = EXCLUDED.category,
    cultivation = EXCLUDED.cultivation, notes = EXCLUDED.notes, sort_order = EXCLUDED.sort_order,
    updated_at = now();

INSERT INTO public.cw_crop_targets
    (crop_type_id, metric, period, unit, min_value, optimal_min, optimal_max, max_value, notes, sources)
SELECT ct.id, v.metric, v.period, v.unit, v.min_value, v.optimal_min, v.optimal_max, v.max_value, v.notes, v.sources
FROM (VALUES
    ('tomato', 'soil_temperature', 'all', '°C', 14::numeric, 15::numeric, 20::numeric, NULL::numeric, 'All day; Root-zone target; below 14 °C phosphorus uptake is strongly restricted with sustained exposure. No defensible upper soil injury threshold established.', ARRAY['https://www.pref.okayama.jp/uploaded/life/817942_7706090_misc.pdf', 'https://www.fao.org/4/i3284e/i3284e.pdf']::text[]),
    ('tomato', 'soil_water_tension', 'all', 'kPa', NULL::numeric, 9.81::numeric, 19.57::numeric, 98.07::numeric, 'All day; positive matric suction from pF 2–2.3; low values are wet and the general dry-stress reference is pF 3.0. No duration-independent waterlogging threshold established.', ARRAY['https://www.hro.or.jp/agricultural/center/result/kenkyuseika/gaiyosho/S52gaiyo/1976053.htm', 'https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2021WR031600', 'https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ktuti6.pdf']::text[]),
    ('tomato', 'soil_moisture', 'all', '%', 12.5::numeric, 19.3::numeric, 24.2::numeric, NULL::numeric, 'All day; Conventional fruit production, not deliberate high-Brix drought; pF 2–2.3 converted to loam % VWC with Carsel–Parrish/van Genuchten parameters; texture changes the band. Dry limit is pF 3 a general growth-inhibition reference; no duration-independent wet injury limit established.', ARRAY['https://www.hro.or.jp/agricultural/center/result/kenkyuseika/gaiyosho/S52gaiyo/1976053.htm', 'https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2021WR031600', 'https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ktuti6.pdf']::text[]),
    ('tomato', 'soil_ec', 'all', 'mS/cm', NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric, 'All day; no defensible bulk-probe target found in the sensor/soil-solution literature searched for this crop. Extract and pore-water EC cannot be converted without soil, moisture and instrument calibration; all bounds remain null.', '{}'::text[]),
    ('tomato', 'soil_ec_1to5', 'all', 'mS/cm', NULL::numeric, 0.2::numeric, 0.5::numeric, NULL::numeric, 'All day; Gunma EC(1:5) soil:water lab-extract management band, with no conversion to bulk EC. Crop injury endpoints are unestablished.', ARRAY['https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/gum14.pdf', 'https://aic.pref.gunma.jp/agriculturals/management_support/soil02/土壌の化学性の測定-1']::text[]),
    ('tomato', 'soil_ph', 'all', 'pH', NULL::numeric, 6::numeric, 6.5::numeric, NULL::numeric, 'All day; Soil pH(H₂O) management band; crop-specific damage limits are not established.', ARRAY['https://www.ja-nakanoshi.iijan.or.jp/hubfs/JA-nakanoshi2023/docs/about/pr_magazine/2020_03_No180.pdf']::text[]),
    ('tomato', 'air_temperature', 'day', '°C', 12::numeric, 20::numeric, 25::numeric, 35::numeric, 'Day; 12 °C is a reproductive cold-stress threshold (malformed/zipper fruit below this temperature), replacing the former 5 °C growth-limit value. Injury depends on duration and cultivar.', ARRAY['https://www.pref.okayama.jp/uploaded/life/817942_7706090_misc.pdf', 'https://www.pref.shimane.lg.jp/industry/norin/gijutsu/nougyo_tech/fukyui/kisyousaigai/setugai.html']::text[]),
    ('tomato', 'air_temperature', 'night', '°C', 12::numeric, 13::numeric, 18::numeric, NULL::numeric, 'Night; 13–18 °C production band, with 12 °C reproductive cold-stress warning from Shimane. A separate night heat-injury threshold is unestablished.', ARRAY['https://www.pref.okayama.jp/uploaded/life/817942_7706090_misc.pdf', 'https://www.pref.shimane.lg.jp/industry/norin/gijutsu/nougyo_tech/fukyui/kisyousaigai/setugai.html']::text[]),
    ('tomato', 'air_humidity', 'day', '%', NULL::numeric, 60::numeric, 80::numeric, NULL::numeric, 'Day; Daytime crop-management band; no duration-independent RH injury thresholds established.', ARRAY['https://www.maff.go.jp/j/kanbo/kankyo/seisaku/climate/report2018/attach/pdf/report-92.pdf']::text[]),
    ('tomato', 'air_humidity', 'night', '%', NULL::numeric, 65::numeric, 75::numeric, 90::numeric, 'Night; Tennessee Extension specifies 65–75% RH for greenhouse tomato. NC State recommends staying below 90% for Botrytis control (infection with 4–6 h free water); a low-RH injury limit is unestablished.', ARRAY['https://content.ces.ncsu.edu/botrytis-gray-mold-of-tomato', 'https://rutherford.tennessee.edu/wp-content/uploads/sites/200/2022/05/W017-Controlling-the-Environment-in-Greenhouses-Used-for-Tomato-Production.pdf']::text[]),
    ('tomato', 'co2', 'day', 'ppm', NULL::numeric, 600::numeric, 900::numeric, NULL::numeric, 'Day; Greenhouse enrichment while vents are closed in the morning; reduce toward 500 ppm before ventilation. Open-field use requires ambient 400–450 ppm instead; crop injury limits unestablished.', ARRAY['https://www.pref.chiba.lg.jp/ninaite/network/field-r6/documents/tomato.pdf']::text[]),
    ('tomato', 'ppfd', 'day', 'µmol/m²/s', NULL::numeric, 463::numeric, 1296::numeric, NULL::numeric, 'Day; lower bound delivers DLI 20 over representative 12 h natural daylight; leaf saturation is 70,000 lux ÷ 54 for sunlight. No transferable mature-canopy photodamage or low-light injury threshold; recalculate lower bound for local daylength and do not equate saturation with daily mean light.', ARRAY['https://www.pubs.ext.vt.edu/SPES/spes-720/spes-720.html', 'https://www.pref.aichi.jp/uploaded/attachment/412058.pdf', 'https://ceac.arizona.edu/sites/default/files/thimijan_-_photmetric_radiometric_and_quantum_light_units.pdf', 'https://www.fao.org/4/x0490e/x0490e07.htm']::text[]),
    ('tomato', 'dli', 'all', 'mol/m²/day', NULL::numeric, 20::numeric, 30::numeric, NULL::numeric, 'All day; Fruiting-crop daily PAR target; tomato guidance is also used for cherry tomato. No demonstrated daily injury endpoints; 30 is not a damage threshold.', ARRAY['https://www.pubs.ext.vt.edu/SPES/spes-720/spes-720.html']::text[]),
    ('tomato', 'vpd', 'day', 'kPa', NULL::numeric, 0.41::numeric, 0.82::numeric, NULL::numeric, 'Day; published humidity deficit 3–6 g/m³ converted at 22.5 °C. Leaf temperature is assumed equal to air; distinct injury endpoints are unestablished.', ARRAY['https://www.pref.chiba.lg.jp/ninaite/network/field-r4/shisetsu-2022-05.html', 'https://www.fao.org/4/x0490e/x0490e07.htm']::text[]),
    ('cherry_tomato', 'soil_temperature', 'all', '°C', 14::numeric, 15::numeric, 20::numeric, NULL::numeric, 'All day; Root-zone target; below 14 °C phosphorus uptake is strongly restricted with sustained exposure. No defensible upper soil injury threshold established; tomato-species proxy.', ARRAY['https://www.pref.okayama.jp/uploaded/life/817942_7706090_misc.pdf', 'https://www.fao.org/4/i3284e/i3284e.pdf']::text[]),
    ('cherry_tomato', 'soil_water_tension', 'all', 'kPa', NULL::numeric, 9.81::numeric, 19.57::numeric, 98.07::numeric, 'All day; Awa cherry-tomato guidance from third-truss flowering manages around pF 2.0 with upper limit 2.3 (9.81–19.57 kPa). General dry stress is pF 3.0; a waterlogging threshold is unestablished.', ARRAY['https://www.city.awa.lg.jp/docs/2015020400028/file_contents/2015020400028_docs_2015020400028_file_contents_BOOK.pdf', 'https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2021WR031600', 'https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ktuti6.pdf']::text[]),
    ('cherry_tomato', 'soil_moisture', 'all', '%', 12.5::numeric, 19.3::numeric, 24.2::numeric, NULL::numeric, 'All day; cherry-tomato pF 2.0–2.3 converted with the stated loam retention curve; texture changes this band, especially in volcanic-ash soil. Dry limit uses general pF 3.0 growth inhibition; no wet-injury endpoint established.', ARRAY['https://www.city.awa.lg.jp/docs/2015020400028/file_contents/2015020400028_docs_2015020400028_file_contents_BOOK.pdf', 'https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2021WR031600', 'https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ktuti6.pdf']::text[]),
    ('cherry_tomato', 'soil_ec', 'all', 'mS/cm', NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric, 'All day; no defensible bulk-probe target found in the sensor/soil-solution literature searched for this crop. Extract and pore-water EC cannot be converted without soil, moisture and instrument calibration; all bounds remain null.', '{}'::text[]),
    ('cherry_tomato', 'soil_ec_1to5', 'all', 'mS/cm', NULL::numeric, 0.2::numeric, 0.5::numeric, NULL::numeric, 'All day; tomato-species proxy using the Gunma EC(1:5) soil:water lab-extract management band. No conversion to bulk EC or established injury endpoints.', ARRAY['https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/gum14.pdf', 'https://aic.pref.gunma.jp/agriculturals/management_support/soil02/土壌の化学性の測定-1']::text[]),
    ('cherry_tomato', 'soil_ph', 'all', 'pH', NULL::numeric, 6::numeric, 6.5::numeric, NULL::numeric, 'All day; Soil pH(H₂O) management band; crop-specific damage limits are not established; tomato-species proxy.', ARRAY['https://www.ja-nakanoshi.iijan.or.jp/hubfs/JA-nakanoshi2023/docs/about/pr_magazine/2020_03_No180.pdf']::text[]),
    ('cherry_tomato', 'air_temperature', 'day', '°C', 12::numeric, 25::numeric, 30::numeric, 35::numeric, 'Day; Awa cherry-tomato production band is 25–30 °C. The 12 °C reproductive cold-stress and 35 °C heat bounds are tomato-species proxies with cultivar/duration dependence.', ARRAY['https://www.pref.okayama.jp/uploaded/life/817942_7706090_misc.pdf', 'https://www.pref.shimane.lg.jp/industry/norin/gijutsu/nougyo_tech/fukyui/kisyousaigai/setugai.html', 'https://www.city.awa.lg.jp/docs/2015020400028/file_contents/2015020400028_docs_2015020400028_file_contents_BOOK.pdf']::text[]),
    ('cherry_tomato', 'air_temperature', 'night', '°C', 12::numeric, 12::numeric, 16::numeric, NULL::numeric, 'Night; Aichi prescribes cherry tomato 2–3 °C above its scheduled tomato night settings of 10–13 °C, giving a 12–16 °C envelope. The 12 °C cold-stress bound is a tomato-species proxy; no night heat-injury threshold established.', ARRAY['https://www.pref.aichi.jp/uploaded/attachment/430612.pdf', 'https://www.pref.shimane.lg.jp/industry/norin/gijutsu/nougyo_tech/fukyui/kisyousaigai/setugai.html']::text[]),
    ('cherry_tomato', 'air_humidity', 'day', '%', NULL::numeric, 60::numeric, 80::numeric, NULL::numeric, 'Day; Daytime crop-management band; no duration-independent RH injury thresholds established; tomato-species proxy.', ARRAY['https://www.maff.go.jp/j/kanbo/kankyo/seisaku/climate/report2018/attach/pdf/report-92.pdf']::text[]),
    ('cherry_tomato', 'air_humidity', 'night', '%', NULL::numeric, 65::numeric, 75::numeric, 90::numeric, 'Night; Tennessee Extension specifies 65–75% RH for greenhouse tomato (tomato-species proxy for cherry tomato). NC State recommends staying below 90% for Botrytis control (infection with 4–6 h free water); a low-RH injury limit is unestablished.', ARRAY['https://content.ces.ncsu.edu/botrytis-gray-mold-of-tomato', 'https://rutherford.tennessee.edu/wp-content/uploads/sites/200/2022/05/W017-Controlling-the-Environment-in-Greenhouses-Used-for-Tomato-Production.pdf']::text[]),
    ('cherry_tomato', 'co2', 'day', 'ppm', NULL::numeric, 600::numeric, 900::numeric, NULL::numeric, 'Day; Greenhouse enrichment while vents are closed in the morning; reduce toward 500 ppm before ventilation. Open-field use requires ambient 400–450 ppm instead; crop injury limits unestablished; tomato-species proxy.', ARRAY['https://www.pref.chiba.lg.jp/ninaite/network/field-r6/documents/tomato.pdf']::text[]),
    ('cherry_tomato', 'ppfd', 'day', 'µmol/m²/s', NULL::numeric, 463::numeric, 1296::numeric, NULL::numeric, 'Day; lower bound delivers DLI 20 over representative 12 h natural daylight; leaf saturation is 70,000 lux ÷ 54 for sunlight (tomato-species proxy). No transferable mature-canopy photodamage or low-light injury threshold; recalculate lower bound for local daylength and do not equate saturation with daily mean light.', ARRAY['https://www.pubs.ext.vt.edu/SPES/spes-720/spes-720.html', 'https://www.pref.aichi.jp/uploaded/attachment/412058.pdf', 'https://ceac.arizona.edu/sites/default/files/thimijan_-_photmetric_radiometric_and_quantum_light_units.pdf', 'https://www.fao.org/4/x0490e/x0490e07.htm']::text[]),
    ('cherry_tomato', 'dli', 'all', 'mol/m²/day', NULL::numeric, 20::numeric, 30::numeric, NULL::numeric, 'All day; Fruiting-crop daily PAR target; tomato guidance is also used for cherry tomato. No demonstrated daily injury endpoints; 30 is not a damage threshold; tomato-species proxy.', ARRAY['https://www.pubs.ext.vt.edu/SPES/spes-720/spes-720.html']::text[]),
    ('cherry_tomato', 'vpd', 'day', 'kPa', NULL::numeric, 0.42::numeric, 0.83::numeric, NULL::numeric, 'Day; tomato-species proxy; published humidity deficit 3–6 g/m³ converted at 27.5 °C. Leaf temperature is assumed equal to air; distinct injury endpoints are unestablished.', ARRAY['https://www.pref.chiba.lg.jp/ninaite/network/field-r4/shisetsu-2022-05.html', 'https://www.fao.org/4/x0490e/x0490e07.htm']::text[]),
    ('cucumber', 'soil_temperature', 'all', '°C', NULL::numeric, 18::numeric, 25::numeric, NULL::numeric, 'All day; Root-zone growing-medium target applied to soil at 10–15 cm; crop-specific soil injury limits were not established.', ARRAY['https://www.pref.okayama.jp/uploaded/life/817942_7706090_misc.pdf']::text[]),
    ('cucumber', 'soil_water_tension', 'all', 'kPa', NULL::numeric, 3.1::numeric, 15.54::numeric, 98.07::numeric, 'All day; positive matric suction from pF 1.5–2.2; low values are wet and the general dry-stress reference is pF 3.0. No duration-independent waterlogging threshold established.', ARRAY['https://www.pref.kagoshima.jp/ao08/chiiki/osumi/sangyo/nougyou/gijutsu/kimo_cucumber_cultivation.html', 'https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2021WR031600', 'https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ktuti6.pdf']::text[]),
    ('cucumber', 'soil_moisture', 'all', '%', 12.5::numeric, 20.8::numeric, 34.2::numeric, NULL::numeric, 'All day; Established soil-grown crop; pF 1.5–2.2 converted to loam % VWC with Carsel–Parrish/van Genuchten parameters; texture changes the band. Dry limit is pF 3 a general growth-inhibition reference; no duration-independent wet injury limit established.', ARRAY['https://www.pref.kagoshima.jp/ao08/chiiki/osumi/sangyo/nougyou/gijutsu/kimo_cucumber_cultivation.html', 'https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2021WR031600', 'https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ktuti6.pdf']::text[]),
    ('cucumber', 'soil_ec', 'all', 'mS/cm', NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric, 'All day; no defensible bulk-probe target found in the sensor/soil-solution literature searched for this crop. Extract and pore-water EC cannot be converted without soil, moisture and instrument calibration; all bounds remain null.', '{}'::text[]),
    ('cucumber', 'soil_ec_1to5', 'all', 'mS/cm', NULL::numeric, 0.4::numeric, 0.5::numeric, NULL::numeric, 'All day; Gunma EC(1:5) soil:water lab-extract management band, with no conversion to bulk EC. Crop injury endpoints are unestablished.', ARRAY['https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/gum14.pdf', 'https://aic.pref.gunma.jp/agriculturals/management_support/soil02/土壌の化学性の測定-1']::text[]),
    ('cucumber', 'soil_ph', 'all', 'pH', NULL::numeric, 6::numeric, 6.5::numeric, NULL::numeric, 'All day; Kagoshima soil management band, treated as pH(H₂O); no crop-specific damage limits established.', ARRAY['https://www.pref.kagoshima.jp/ao08/chiiki/osumi/sangyo/nougyou/gijutsu/kimo_cucumber_cultivation.html']::text[]),
    ('cucumber', 'air_temperature', 'day', '°C', 8::numeric, 23::numeric, 28::numeric, 35::numeric, 'Day; Daytime production; night 10–15 °C. Limits describe growth/reproductive stress, not instantaneous lethal temperatures.', ARRAY['https://www.pref.okayama.jp/uploaded/life/817942_7706090_misc.pdf']::text[]),
    ('cucumber', 'air_temperature', 'night', '°C', 8::numeric, 10::numeric, 15::numeric, NULL::numeric, 'Night; published night production band; low bound describes growth/reproductive stress with sustained exposure. No separate night heat-damage threshold established.', ARRAY['https://www.pref.okayama.jp/uploaded/life/817942_7706090_misc.pdf']::text[]),
    ('cucumber', 'air_humidity', 'day', '%', NULL::numeric, 70::numeric, 80::numeric, NULL::numeric, 'Day; Daytime crop-management band; no duration-independent RH injury thresholds established.', ARRAY['https://www.pref.kagoshima.jp/ao08/chiiki/osumi/sangyo/nougyou/gijutsu/kimo_cucumber_cultivation.html']::text[]),
    ('cucumber', 'air_humidity', 'night', '%', NULL::numeric, NULL::numeric, NULL::numeric, 93::numeric, 'Night; 93% RH is a general greenhouse Botrytis-risk proxy associated with 8–12 h wetness at 13–18 °C, not a crop-specific instantaneous injury threshold. No defensible separate night optimum or low-RH injury limit established.', ARRAY['https://ipm.cahnr.uconn.edu/botrytis-blight-on-greenhouse-crops/']::text[]),
    ('cucumber', 'co2', 'day', 'ppm', NULL::numeric, 600::numeric, 900::numeric, NULL::numeric, 'Day; Greenhouse enrichment while vents are closed in the morning; reduce toward 500 ppm before ventilation. Open-field use requires ambient 400–450 ppm instead; crop injury limits unestablished.', ARRAY['https://www.pref.chiba.lg.jp/ninaite/network/field-r6/documents/tomato.pdf']::text[]),
    ('cucumber', 'ppfd', 'day', 'µmol/m²/s', NULL::numeric, 463::numeric, 1019::numeric, 1500::numeric, 'Day; lower bound delivers DLI 20 over representative 12 h daylight (recalculate locally); saturation is 55,000 lux ÷ 54 for sunlight. The 1500 warning is the start of reported photoinhibition at 1500–1800 in Jinyou 35 leaf-chamber measurements at 20–24 °C/50% RH; low-light injury is unquantified.', ARRAY['https://www.pubs.ext.vt.edu/SPES/spes-720/spes-720.html', 'https://www.pref.aichi.jp/uploaded/attachment/412058.pdf', 'https://ceac.arizona.edu/sites/default/files/thimijan_-_photmetric_radiometric_and_quantum_light_units.pdf', 'https://www.fao.org/4/x0490e/x0490e07.htm', 'https://mdpi-res.com/d_attachment/agriculture/agriculture-13-00204/article_deploy/agriculture-13-00204.pdf']::text[]),
    ('cucumber', 'dli', 'all', 'mol/m²/day', NULL::numeric, 20::numeric, 30::numeric, NULL::numeric, 'All day; Fruiting-crop daily PAR target; tomato guidance is also used for cherry tomato. No demonstrated daily injury endpoints; 30 is not a damage threshold.', ARRAY['https://www.pubs.ext.vt.edu/SPES/spes-720/spes-720.html']::text[]),
    ('cucumber', 'vpd', 'day', 'kPa', NULL::numeric, 0.41::numeric, 0.83::numeric, NULL::numeric, 'Day; published humidity deficit 3–6 g/m³ converted at 25.5 °C. Leaf temperature is assumed equal to air; distinct injury endpoints are unestablished.', ARRAY['https://www.nogyo.tosa.pref.kochi.lg.jp/download/?fid=56891&id=6967&t=LD', 'https://www.fao.org/4/x0490e/x0490e07.htm']::text[]),
    ('sweet_pepper', 'soil_temperature', 'all', '°C', NULL::numeric, 18::numeric, 24::numeric, NULL::numeric, 'All day; Root-zone growing-medium target applied to soil at 10–15 cm; crop-specific soil injury limits were not established.', ARRAY['https://www.pref.fukushima.lg.jp/uploaded/attachment/733638.pdf']::text[]),
    ('sweet_pepper', 'soil_water_tension', 'all', 'kPa', NULL::numeric, 4.91::numeric, 19.57::numeric, 98.07::numeric, 'All day; pF 1.7–2.3 converts to 4.91–19.57 kPa, a provisional envelope spanning fertigation targets and winter greenhouse irrigation triggers, not a published start/stop pair or a universal paprika optimum. Retained null wet-injury limit and 98.07 kPa dry limit (pF 3.0, a general soil growth-inhibition proxy); paprika pF 1.7 irrigation must not be delayed to pF 2.3.', ARRAY['https://www.pref.ibaraki.jp/nourinsuisan/nosose/cont/img/16_hukyuseika_08.pdf', 'https://www.pref.kagoshima.jp/ao08/chiiki/osumi/sangyo/nougyou/gijutsu/kimo_seetpepper_cultivation.html', 'https://www.nogyo.tosa.pref.kochi.lg.jp/download/?fid=25677&id=5634&t=LD', 'https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ktuti6.pdf']::text[]),
    ('sweet_pepper', 'soil_moisture', 'all', '%', 12.5::numeric, 19.3::numeric, 30.2::numeric, NULL::numeric, 'All day; pF 1.7–2.3 gives 19.3–30.2% VWC using θ=0.078+(0.430−0.078)/[1+(0.036h)^1.56]^(1−1/1.56), h=10^pF cm, multiplied by 100; this is the supplied Carsel–Parrish loam curve, and volcanic-ash soils require local calibration. Retained 12.5% dry limit (general pF 3.0 proxy) and null wet limit; the band combines method/season targets, not irrigation stop/start settings.', ARRAY['https://www.pref.ibaraki.jp/nourinsuisan/nosose/cont/img/16_hukyuseika_08.pdf', 'https://www.pref.kagoshima.jp/ao08/chiiki/osumi/sangyo/nougyou/gijutsu/kimo_seetpepper_cultivation.html', 'https://www.nogyo.tosa.pref.kochi.lg.jp/download/?fid=25677&id=5634&t=LD', 'https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ktuti6.pdf', 'https://www.pref.fukushima.lg.jp/uploaded/attachment/733638.pdf']::text[]),
    ('sweet_pepper', 'soil_ec', 'all', 'mS/cm', NULL::numeric, 0.5::numeric, 0.7::numeric, NULL::numeric, 'All day; Fukushima gives 0.5–0.7 mS/cm during harvest for an installed Farmo sensor at 15 cm, retained without extract conversion. Instrument-specific guidance requires a CropWatch calibration check; salt-injury and low-EC injury endpoints are unestablished.', ARRAY['https://www.pref.fukushima.lg.jp/uploaded/attachment/733638.pdf']::text[]),
    ('sweet_pepper', 'soil_ec_1to5', 'all', 'mS/cm', NULL::numeric, 0.5::numeric, 1.0::numeric, NULL::numeric, 'All day; Saga rain-shelter pepper EC(1:5) lab-extract target during growth; preplant target is different. No conversion to bulk EC, and the table’s low/high diagnostic classes are not proven injury endpoints.', ARRAY['https://www.pref.saga.lg.jp/kiji003101843/3_101843_up_m5lirohr.pdf']::text[]),
    ('sweet_pepper', 'soil_ph', 'all', 'pH', NULL::numeric, 6::numeric, 6.5::numeric, NULL::numeric, 'All day; Soil pH(H₂O) management band; crop-specific damage limits are not established.', ARRAY['https://www.ja-nakanoshi.iijan.or.jp/hubfs/JA-nakanoshi2023/docs/about/pr_magazine/2020_03_No180.pdf']::text[]),
    ('sweet_pepper', 'air_temperature', 'day', '°C', 15::numeric, 20::numeric, 28::numeric, 33::numeric, 'Day; Daytime production; night 18–20 °C. Limits describe growth/reproductive stress, not instantaneous lethal temperatures.', ARRAY['https://www.pref.fukushima.lg.jp/uploaded/attachment/733638.pdf']::text[]),
    ('sweet_pepper', 'air_temperature', 'night', '°C', 15::numeric, 18::numeric, 20::numeric, NULL::numeric, 'Night; published night production band; low bound describes growth/reproductive stress with sustained exposure. No separate night heat-damage threshold established.', ARRAY['https://www.pref.fukushima.lg.jp/uploaded/attachment/733638.pdf']::text[]),
    ('sweet_pepper', 'air_humidity', 'day', '%', NULL::numeric, 72.4::numeric, 86.2::numeric, NULL::numeric, 'Day; derived at 24 °C from the NARO/Oita paprika target of 3–6 g/m³ humidity deficit, replacing the Fukushima pepper 80–90% target. Adjust RH with temperature using VPD; daytime injury endpoints are unestablished.', ARRAY['https://www.naro.go.jp/publicity_report/publication/files/Large-scale_facility_gardening_manual_Oita.pdf', 'https://www.fao.org/4/x0490e/x0490e07.htm']::text[]),
    ('sweet_pepper', 'air_humidity', 'night', '%', NULL::numeric, NULL::numeric, NULL::numeric, 93::numeric, 'Night; 93% RH is a general greenhouse Botrytis-risk proxy associated with 8–12 h wetness at 13–18 °C, not a crop-specific instantaneous injury threshold. No defensible separate night optimum or low-RH injury limit established.', ARRAY['https://ipm.cahnr.uconn.edu/botrytis-blight-on-greenhouse-crops/']::text[]),
    ('sweet_pepper', 'co2', 'day', 'ppm', NULL::numeric, 600::numeric, 1000::numeric, NULL::numeric, 'Day; Kochi winter paprika morning schedule: about 1000 ppm before ventilation, then 600 ppm until noon; afternoon about 400 ppm. This spans scheduled setpoints; open-field target is ambient 400–450 ppm and injury limits are unknown.', ARRAY['https://www.nogyo.tosa.pref.kochi.lg.jp/download/?fid=26689&id=5701&t=LD']::text[]),
    ('sweet_pepper', 'ppfd', 'day', 'µmol/m²/s', NULL::numeric, 463::numeric, 741::numeric, NULL::numeric, 'Day; lower bound delivers DLI 20 over representative 12 h natural daylight; leaf saturation is 40,000 lux ÷ 54 for sunlight. No quantified photodamage or low-light injury threshold; recalculate lower bound for local daylength and do not equate saturation with daily mean light.', ARRAY['https://ongreenhousevegetables.ca/2023/09/06/finding-the-right-light-recipe/', 'https://www.pref.fukushima.lg.jp/uploaded/attachment/733638.pdf', 'https://ceac.arizona.edu/sites/default/files/thimijan_-_photmetric_radiometric_and_quantum_light_units.pdf', 'https://www.fao.org/4/x0490e/x0490e07.htm']::text[]),
    ('sweet_pepper', 'dli', 'all', 'mol/m²/day', NULL::numeric, 20::numeric, NULL::numeric, NULL::numeric, 'All day; AAFC/OMAFRA guidance places highest yields above 20 mol/m²/day; no bounded optimum upper endpoint or daily injury thresholds established.', ARRAY['https://ongreenhousevegetables.ca/2023/09/06/finding-the-right-light-recipe/']::text[]),
    ('sweet_pepper', 'vpd', 'day', 'kPa', NULL::numeric, 0.41::numeric, 0.82::numeric, NULL::numeric, 'Day; published humidity deficit 3–6 g/m³ converted at 24 °C. Leaf temperature is assumed equal to air; distinct injury endpoints are unestablished.', ARRAY['https://www.naro.go.jp/publicity_report/publication/files/Large-scale_facility_gardening_manual_Oita.pdf', 'https://www.fao.org/4/x0490e/x0490e07.htm']::text[]),
    ('poblano_pepper', 'soil_temperature', 'all', '°C', NULL::numeric, 18::numeric, 24::numeric, NULL::numeric, 'Bell pepper (sweet_pepper) proxy: no poblano-specific research was found. All day; Root-zone growing-medium target applied to soil at 10–15 cm; crop-specific soil injury limits were not established.', ARRAY['https://www.pref.fukushima.lg.jp/uploaded/attachment/733638.pdf']::text[]),
