    ('strawberry', 'soil_temperature', 'all', '°C', NULL::numeric, 18::numeric, 21::numeric, NULL::numeric, 'All day; Root-zone growing-medium target applied to soil at 10–15 cm; crop-specific soil injury limits were not established.', ARRAY['https://www.pref.okayama.jp/uploaded/life/817942_7706090_misc.pdf']::text[]),
    ('strawberry', 'soil_water_tension', 'all', 'kPa', NULL::numeric, 7.79::numeric, 19.57::numeric, 98.07::numeric, 'All day; positive matric suction from pF 1.9–2.3; low values are wet and the general dry-stress reference is pF 3.0. No duration-independent waterlogging threshold established.', ARRAY['https://www.pref.tochigi.lg.jp/g61/seika/documents/sep_022_34.pdf', 'https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2021WR031600', 'https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ktuti6.pdf']::text[]),
    ('strawberry', 'soil_moisture', 'all', '%', 12.5::numeric, 19.3::numeric, 26.1::numeric, NULL::numeric, 'All day; Tochiotome raised soil beds; source measured at 15 cm; pF 1.9–2.3 converted to loam % VWC with Carsel–Parrish/van Genuchten parameters; texture changes the band. Dry limit is pF 3 a general growth-inhibition reference; no duration-independent wet injury limit established.', ARRAY['https://www.pref.tochigi.lg.jp/g61/seika/documents/sep_022_34.pdf', 'https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2021WR031600', 'https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ktuti6.pdf']::text[]),
    ('strawberry', 'soil_ec', 'all', 'mS/cm', NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric, 'All day; no defensible bulk-probe target found in the sensor/soil-solution literature searched for this crop. Extract and pore-water EC cannot be converted without soil, moisture and instrument calibration; all bounds remain null.', '{}'::text[]),
    ('strawberry', 'soil_ec_1to5', 'all', 'mS/cm', NULL::numeric, 0.1::numeric, 0.2::numeric, NULL::numeric, 'All day; Gunma EC(1:5) soil:water lab-extract management band, with no conversion to bulk EC. Crop injury endpoints are unestablished.', ARRAY['https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/gum14.pdf', 'https://aic.pref.gunma.jp/agriculturals/management_support/soil02/土壌の化学性の測定-1']::text[]),
    ('strawberry', 'soil_ph', 'all', 'pH', NULL::numeric, 5.5::numeric, 6.5::numeric, NULL::numeric, 'All day; Soil pH(H₂O), Gunma greenhouse strawberry standard; damage limits not established.', ARRAY['https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/gum14.pdf']::text[]),
    ('strawberry', 'air_temperature', 'day', '°C', 5::numeric, 18::numeric, 23::numeric, 30::numeric, 'Day; Daytime general production band; night 5–10 °C. Below 5 °C the source warns of reproductive impairment/dormancy; upper limit is the general 30 °C growth limit, with duration/cultivar dependence.', ARRAY['https://www.pref.okayama.jp/uploaded/life/817942_7706090_misc.pdf']::text[]),
    ('strawberry', 'air_temperature', 'night', '°C', 5::numeric, 5::numeric, 10::numeric, NULL::numeric, 'Night; published night production band; low bound describes growth/reproductive stress with sustained exposure. No separate night heat-damage threshold established.', ARRAY['https://www.pref.okayama.jp/uploaded/life/817942_7706090_misc.pdf']::text[]),
    ('strawberry', 'air_humidity', 'day', '%', NULL::numeric, 75::numeric, 80::numeric, NULL::numeric, 'Day; Aichi winter forcing greenhouse management target for December–March is 75–80% RH, replacing the indoor-culture 40–60% band. Duration-independent daytime injury endpoints are unestablished.', ARRAY['https://www.pref.aichi.jp/uploaded/attachment/483809.pdf']::text[]),
    ('strawberry', 'air_humidity', 'night', '%', NULL::numeric, NULL::numeric, NULL::numeric, 93::numeric, 'Night; 93% RH is a general greenhouse Botrytis-risk proxy associated with 8–12 h wetness at 13–18 °C, not a crop-specific instantaneous injury threshold. No defensible separate night optimum or low-RH injury limit established.', ARRAY['https://ipm.cahnr.uconn.edu/botrytis-blight-on-greenhouse-crops/']::text[]),
    ('strawberry', 'co2', 'day', 'ppm', NULL::numeric, 800::numeric, 1000::numeric, NULL::numeric, 'Day; Daytime greenhouse enrichment; Tottori guidance for Totteoki is a cultivar proxy. No crop-specific depletion or toxicity threshold established.', ARRAY['https://www.pref.tottori.lg.jp/secure/616031/1totteoki-CO2.pdf']::text[]),
    ('strawberry', 'ppfd', 'day', 'µmol/m²/s', NULL::numeric, 556::numeric, 1000::numeric, NULL::numeric, 'Retained 556 µmol/m²/s because the retained lower DLI of 20 requires 20/(10×0.0036)=555.6 over representative 10 h natural winter daylight; recalculate for local date and latitude. Retained Tochiotome saturation of 1000 at 400 ppm CO₂ and null injury endpoints; saturation rises under CO₂ enrichment.', ARRAY['https://www.naro.go.jp/laboratory/karc/prefectural_results/files/0_27_all.pdf', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9965992/', 'https://www.jstage.jst.go.jp/article/jcs/79/2/79_2_192/_article/-char/ja']::text[]),
    ('strawberry', 'dli', 'all', 'mol/m²/day', NULL::numeric, 20::numeric, 25::numeric, NULL::numeric, 'Retained 20–25 mol/m²/day as a provisional greenhouse production target: Japanese forcing research supports supplemented DLI ≥20, but no lower Japanese winter optimum was verified and 25 remains an overseas-guidance proxy. Retained null low-stress limit and replaced 30 with null because a transferable daily injury threshold for Japanese forcing cultivars was not established.', ARRAY['https://www.naro.go.jp/laboratory/karc/prefectural_results/files/0_27_all.pdf', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9965992/']::text[]),
    ('strawberry', 'vpd', 'day', 'kPa', NULL::numeric, 0.41::numeric, 0.81::numeric, NULL::numeric, 'Day; general enriched fruiting-greenhouse guidance including forcing strawberry; published humidity deficit 3–6 g/m³ converted at 20.5 °C. Leaf temperature is assumed equal to air; distinct injury endpoints are unestablished.', ARRAY['https://www.agri.metro.tokyo.lg.jp/fukyu_info/R1fukyu_111.pdf', 'https://www.fao.org/4/x0490e/x0490e07.htm']::text[]),
    ('grape', 'soil_temperature', 'all', '°C', NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric, 'No verified optimum or injury limits for soil-grown Japanese table grapes at 10–15 cm; hydroponic Kyoho root-temperature treatments cannot establish these soil-probe thresholds. All endpoints remain null.', ARRAY['https://www.jstage.jst.go.jp/article/jshita1991/12/1/12_1_53/_article/-char/ja/']::text[]),
    ('grape', 'soil_water_tension', 'all', 'kPa', NULL::numeric, 3.1::numeric, 15.54::numeric, NULL::numeric, 'Provisional seasonal management envelope from Kyoho irrigation triggers pF 1.5–2.2, converted using kPa = 0.0980665 × 10^pF; young berries need the wetter end, not a constant season-long optimum. Wet injury and dry damage limits are unverified and null; Shine Muscat needs earlier irrigation (see NOTES).', ARRAY['https://www.jstage.jst.go.jp/article/ecb1963/29/3/29_3_133/_article/-char/ja/']::text[]),
    ('grape', 'soil_moisture', 'all', '%', NULL::numeric, 20.77::numeric, 34.22::numeric, NULL::numeric, 'Converted from 3.10–15.54 kPa using Carsel–Parrish loam van Genuchten parameters: theta_r=0.078, theta_s=0.430, alpha=0.036/cm, n=1.56, m=1−1/n. Injury endpoints are null with tension; calibrate locally, especially for high-retention 黒ボク土.', ARRAY['https://www.jstage.jst.go.jp/article/ecb1963/29/3/29_3_133/_article/-char/ja/', 'https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2021WR031600']::text[]),
    ('grape', 'soil_ec', 'all', 'mS/cm', NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric, 'No crop-specific moist-soil bulk EC calibration was verified for the CropWatch probe; conductivity depends on water content, temperature and soil properties. Neither extract EC nor nutrient-solution EC can be substituted, so all endpoints are null.', ARRAY['https://scholarworks.uni.edu/jias/vol110/iss3/7/']::text[]),
    ('grape', 'soil_ec_1to5', 'all', 'mS/cm', NULL::numeric, NULL::numeric, 0.1::numeric, NULL::numeric, 'Kanagawa orchard target is EC(1:5), at 25°C, at or below 0.1 dS/m (= mS/cm). No lower nutritional target or crop damage thresholds are supplied, so those endpoints are null.', ARRAY['https://soil-inventory.rad.naro.go.jp/pdf/hiryou/k14%E7%A5%9E%E5%A5%88%E5%B7%9D%E7%9C%8C/%E5%A4%9A%E8%82%A5%E5%9C%B0%E5%B8%AF_%E3%81%9D%E3%81%AE%E4%BB%96/%E6%9E%9C%E6%A8%B9%E6%94%B9%E5%96%84%E7%9B%AE%E6%A8%99.pdf']::text[]),
    ('grape', 'soil_ph', 'all', 'pH', NULL::numeric, 6.0::numeric, 6.5::numeric, NULL::numeric, 'Kanagawa table for grape soils explicitly specifies pH(H2O) 6.0–6.5; cultivar and prefectural targets differ. No supported injury thresholds, so min/max are null.', ARRAY['https://soil-inventory.rad.naro.go.jp/pdf/hiryou/k14%E7%A5%9E%E5%A5%88%E5%B7%9D%E7%9C%8C/%E5%A4%9A%E8%82%A5%E5%9C%B0%E5%B8%AF_%E3%81%9D%E3%81%AE%E4%BB%96/%E6%9E%9C%E6%A8%B9%E6%94%B9%E5%96%84%E7%9B%AE%E6%A8%99.pdf']::text[]),
    ('grape', 'air_temperature', 'day', '°C', -1::numeric, 25::numeric, 28::numeric, 40::numeric, 'Active table-grape growth/fruit enlargement: Japanese guidance gives 25–28°C by day; Delaware growth limits include approximately −1°C cold and 40°C heat with exposure durations around one hour. These are duration-dependent reference limits, not instantaneous universal injury boundaries.', ARRAY['https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ibasiza18.pdf']::text[]),
    ('grape', 'air_temperature', 'night', '°C', -1::numeric, 15::numeric, 18::numeric, NULL::numeric, 'Okayama Shine Muscat fruit-enlargement night target is 15–18°C; Delaware active-tissue frost evidence supplies the provisional −1°C lower limit. A night-specific heat-injury threshold is unverified and null; exclude dormancy.', ARRAY['https://www.pref.okayama.jp/uploaded/life/817942_7706089_misc.pdf', 'https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ibasiza18.pdf']::text[]),
    ('grape', 'air_humidity', 'day', '%', NULL::numeric, 50::numeric, 60::numeric, 92::numeric, 'Japanese table-grape guidance includes 50–60% RH in the later growing stages; the low-RH injury limit is unverified and null. UC reports severe late-season Botrytis above 92% with fruit-surface water and moderate temperatures; max is conditional disease risk.', ARRAY['https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ibasiza18.pdf', 'https://ipm.ucanr.edu/agriculture/grape/botrytis-bunch-rot/']::text[]),
    ('grape', 'air_humidity', 'night', '%', NULL::numeric, NULL::numeric, NULL::numeric, 92::numeric, 'Above 92% RH, free water and 14.4–27.8°C favor severe late-season grape Botrytis; this is a conditional night disease-risk ceiling. No verified night optimum or low-RH injury endpoint, so these are null.', ARRAY['https://ipm.ucanr.edu/agriculture/grape/botrytis-bunch-rot/']::text[]),
    ('grape', 'co2', 'day', 'ppm', NULL::numeric, 400::numeric, 450::numeric, NULL::numeric, 'Open-field/rain-shelter default uses the brief’s ambient band, supported by NOAA background observations around 426 ppm; it is not an enrichment target. No verified Japanese table-grape greenhouse enrichment or crop-damage limits, so min/max remain null.', ARRAY['https://gml.noaa.gov/ccgg/trends/']::text[]),
    ('grape', 'ppfd', 'day', 'µmol/m²/s', NULL::numeric, NULL::numeric, 1200::numeric, NULL::numeric, 'Retain 1200 µmol/m²/s from the textbook leaf-saturation range 700–1200 (printed p. 170); this is a provisional leaf reference, not a whole-canopy optimum or damage limit. With no defensible DLI optimal_min, mean-daylight optimal_min remains null and no photoperiod conversion is applied; min/max also remain unverified and null.', ARRAY['https://elearning.unite.it/pluginfile.php/316078/mod_resource/content/1/The%20Science%20of%20Grapevines,%203e%20-%20Sconosciuto_compressed.pdf']::text[]),
    ('grape', 'dli', 'all', 'mol/m²/day', NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric, 'Current null endpoints retained: verified table-grape studies report stage-total radiation, timed supplemental light, or experimental exposures, without establishing a transferable daily canopy production target or stress limit. No daily solar/lux conversion is adopted because exposure duration or daily integration is missing; candidate conversions and limitations are documented in NOTES.md.', ARRAY['https://www.pref.fukui.lg.jp/doc/noushi/kikaku/shiken_d/fil/R7_gyoumu.pdf', 'https://www.researchgate.net/publication/389233719_The_Effects_of_Light_Duration_and_Intensity_with_Supplemental_Light-Emitting_Diode_Lights_on_Grape_Photosynthesis_Yield_and_Fruit_Quality', 'https://www.researchgate.net/publication/386264468_The_PEPCK_and_FBP_Genes_Regulate_Gluconeogenesis_Metabolism_in_Grape_Berries_in_Response_to_Light_Intensity']::text[]),
    ('grape', 'vpd', 'day', 'kPa', NULL::numeric, 1.38::numeric, 1.73::numeric, NULL::numeric, 'Derived, not a published grape VPD target: 50–60% RH at 26.5°C gives 1.38–1.73 kPa, assuming leaf temperature equals air temperature. No defensible injury endpoints; use measured leaf temperature when available.', ARRAY['https://www.maff.go.jp/j/seisan/kankyo/hozen_type/h_sehi_kizyun/pdf/ibasiza18.pdf', 'https://www.fao.org/4/x0490e/x0490e07.htm']::text[])
) AS v (code, metric, period, unit, min_value, optimal_min, optimal_max, max_value, notes, sources)
JOIN public.cw_crop_types ct ON ct.code = v.code
ON CONFLICT (crop_type_id, metric, period) DO UPDATE SET
    unit = EXCLUDED.unit, min_value = EXCLUDED.min_value, optimal_min = EXCLUDED.optimal_min,
    optimal_max = EXCLUDED.optimal_max, max_value = EXCLUDED.max_value, notes = EXCLUDED.notes,
    sources = EXCLUDED.sources, updated_at = now();

-- Let PostgREST (the API's Supabase client) see the new tables and relationship now.
NOTIFY pgrst, 'reload schema';

COMMIT;
